package com.planker;

import com.planker.model.PlankerEvent;
import com.planker.model.QueuedEvent;
import java.util.ArrayDeque;
import java.util.Deque;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class EventQueue
{
    private static final int MAX_QUEUE_SIZE = 500;
    private static final int MAX_PERMANENT_FAILURES = 3;
    private static final long MAX_RESTORED_DELAY_MS = 24 * 60 * 60 * 1000L;
    private final Deque<QueuedEvent> pendingEvents = new ArrayDeque<>();
    private final PlankerApiClient apiClient;
    private final EventQueueStore queueStore;
    private final EventRetryPolicy retryPolicy;
    private final QueuedEventValidator validator;
    private boolean submissionInProgress;
    private boolean pausedForAuthentication;
    private boolean pausedForRequiredUpdate;

    @Inject
    public EventQueue(PlankerApiClient apiClient, EventQueueStore queueStore, EventRetryPolicy retryPolicy, QueuedEventValidator validator)
    {
        this.apiClient = apiClient;
        this.queueStore = queueStore;
        this.retryPolicy = retryPolicy;
        this.validator = validator;
        restorePersistedEvents();
    }

    public synchronized void enqueue(PlankerEvent gameEvent)
    {
        if (!validator.isValid(gameEvent)) { log.warn("Ignored an invalid PlankRS event before queueing"); return; }
        if (pendingEvents.size() >= MAX_QUEUE_SIZE) log.warn("PlankRS queue reached capacity; discarded oldest event {}", validator.eventId(pendingEvents.removeFirst()));
        pendingEvents.addLast(new QueuedEvent(gameEvent));
        saveQueue();
        submitNextEvent();
    }

    private synchronized void submitNextEvent()
    {
        if (submissionInProgress || pausedForAuthentication || pausedForRequiredUpdate || pendingEvents.isEmpty()) return;
        QueuedEvent queuedEvent = pendingEvents.peekFirst();
        if (!validator.isValid(queuedEvent)) { pendingEvents.removeFirst(); saveQueue(); submitNextEvent(); return; }
        if (queuedEvent.getNextAttemptAtEpochMs() > System.currentTimeMillis()) return;
        submissionInProgress = true;
        apiClient.send(queuedEvent.getEvent(), new PlankerApiClient.ResultCallback()
        {
            @Override public void onSuccess() { synchronized (EventQueue.this) { removeMatching(queuedEvent); submissionInProgress=false; saveQueue(); log.debug("Submitted PlankRS event {}",validator.eventId(queuedEvent)); submitNextEvent(); } }
            @Override public void onFailure(PlankerApiClient.ApiFailure failure) { synchronized (EventQueue.this) { handleFailure(queuedEvent,failure); } }
        });
    }

    private void handleFailure(QueuedEvent queuedEvent, PlankerApiClient.ApiFailure failure)
    {
        submissionInProgress = false;
        queuedEvent.setAttemptCount(Math.max(0, queuedEvent.getAttemptCount()) + 1);
        if (failure.isAuthenticationFailure()) { pausedForAuthentication=true; queuedEvent.setNextAttemptAtEpochMs(0L); saveQueue(); log.warn("PlankRS queue paused after an authentication failure"); return; }
        if (failure.isPermanentFailure() && queuedEvent.getAttemptCount() >= MAX_PERMANENT_FAILURES) { removeMatching(queuedEvent); saveQueue(); log.warn("Discarded event {} after {} permanent rejection(s): {}",validator.eventId(queuedEvent),queuedEvent.getAttemptCount(),failure.getMessage()); submitNextEvent(); return; }
        long delay=retryPolicy.calculateDelayMillis(queuedEvent.getAttemptCount(),failure.getRetryAfterMillis());
        queuedEvent.setNextAttemptAtEpochMs(System.currentTimeMillis()+delay);
        saveQueue();
        log.warn("Event {} remains queued; attempt {} will retry in {} second(s): {}",validator.eventId(queuedEvent),queuedEvent.getAttemptCount(),Math.max(1L,delay/1000L),failure.getMessage());
    }

    public synchronized void retryPending(){submitNextEvent();}
    public synchronized void resumeAfterConfigurationChange(){pausedForAuthentication=false;pausedForRequiredUpdate=false;for(QueuedEvent event:pendingEvents)event.setNextAttemptAtEpochMs(0L);saveQueue();submitNextEvent();}
    public synchronized void pauseForRequiredUpdate(){pausedForRequiredUpdate=true;}
    public synchronized int size(){return pendingEvents.size();}

    private void restorePersistedEvents()
    {
        long now=System.currentTimeMillis();
        for(QueuedEvent event:queueStore.load())
        {
            if(!validator.isValid(event))continue;
            event.setAttemptCount(Math.max(0,event.getAttemptCount()));
            if(event.getNextAttemptAtEpochMs()<0L||event.getNextAttemptAtEpochMs()>now+MAX_RESTORED_DELAY_MS)event.setNextAttemptAtEpochMs(0L);
            if(pendingEvents.size()==MAX_QUEUE_SIZE)pendingEvents.removeFirst();
            pendingEvents.addLast(event);
        }
        if(!pendingEvents.isEmpty())log.info("Loaded {} persisted PlankRS event(s)",pendingEvents.size());
    }
    private void saveQueue(){queueStore.save(pendingEvents);}
    private void removeMatching(QueuedEvent expected){if(pendingEvents.peekFirst()==expected)pendingEvents.removeFirst();else{pendingEvents.remove(expected);log.debug("Queue head changed before completion; removed matching queued event by identity");}}
}

package com.planker;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.planker.model.QueuedEvent;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

@Slf4j
public class EventQueueStore
{
    private final Gson gson;
    private final Path storageDirectory;
    private final Path queueFile;

    @Inject
    public EventQueueStore(Gson gson)
    {
        this.gson = gson;
        storageDirectory = RuneLite.RUNELITE_DIR.toPath().resolve("planker");
        queueFile = storageDirectory.resolve("event-queue.json");
    }

    public Collection<QueuedEvent> load()
    {
        try
        {
            Files.createDirectories(storageDirectory);
            if (!Files.exists(queueFile) || Files.size(queueFile) == 0L) return Collections.emptyList();
            QueuedEvent[] events = gson.fromJson(new String(Files.readAllBytes(queueFile), StandardCharsets.UTF_8), QueuedEvent[].class);
            if (events == null) return Collections.emptyList();
            ArrayList<QueuedEvent> result = new ArrayList<>();
            Collections.addAll(result, events);
            return result;
        }
        catch (IOException | JsonParseException exception)
        {
            log.warn("Unable to read the persisted PlankRS queue; removing the unreadable file");
            log.debug("Persisted queue read failure", exception);
            delete();
            return Collections.emptyList();
        }
    }

    public void save(Collection<QueuedEvent> events)
    {
        try
        {
            Files.createDirectories(storageDirectory);
            Path temporaryFile = queueFile.resolveSibling(queueFile.getFileName() + ".tmp");
            Files.write(temporaryFile, gson.toJson(new ArrayList<>(events)).getBytes(StandardCharsets.UTF_8));
            try { Files.move(temporaryFile, queueFile, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE); }
            catch (IOException atomicMoveFailure) { log.debug("Atomic queue replacement unavailable; using standard replacement"); Files.move(temporaryFile, queueFile, StandardCopyOption.REPLACE_EXISTING); }
        }
        catch (IOException exception)
        {
            log.error("Unable to persist the PlankRS event queue: {}", exception.getMessage());
            log.debug("Event queue persistence failure", exception);
        }
    }

    private void delete()
    {
        try { Files.deleteIfExists(queueFile); }
        catch (IOException exception) { log.warn("Unable to remove the unreadable event queue: {}", exception.getMessage()); log.debug("Unreadable queue deletion failure", exception); }
    }
}

package com.planker;

import java.util.concurrent.ThreadLocalRandom;

public class EventRetryPolicy
{
    private static final long MAX_BACKOFF_MS = 15 * 60 * 1000L;
    private static final long[] RETRY_SCHEDULE_MS = {5_000L, 15_000L, 30_000L, 60_000L, 120_000L, 300_000L, 600_000L, 900_000L};

    public long calculateDelayMillis(int attemptCount, long serverRetryAfterMillis)
    {
        if (serverRetryAfterMillis > 0) return Math.min(MAX_BACKOFF_MS, serverRetryAfterMillis);
        int index = Math.min(Math.max(0, attemptCount - 1), RETRY_SCHEDULE_MS.length - 1);
        long baseDelay = RETRY_SCHEDULE_MS[index];
        long jitter = ThreadLocalRandom.current().nextLong(Math.max(1L, baseDelay / 5L));
        return Math.min(MAX_BACKOFF_MS, baseDelay + jitter);
    }
}

package com.planker;

import com.planker.model.PlankerEvent;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Base64;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

@Slf4j
public class LootEventService
{
    private static final long DUPLICATE_WINDOW_MS = 3_000L;
    private static final long DEDUP_ENTRY_MAX_AGE_MS = 30_000L;
    private static final int MAX_IMAGE_BYTES = 1_000_000;

    private final PlankerConfig config;
    private final EventQueue eventQueue;
    private final ItemManager itemManager;
    private final EventImageService imageService;
    private final NotificationPolicyService policyService;
    private final Map<String, Long> recentlyProcessedDrops = new HashMap<>();

    @Inject
    public LootEventService(PlankerConfig config, EventQueue eventQueue, ItemManager itemManager,
        EventImageService imageService, NotificationPolicyService policyService)
    {
        this.config = config;
        this.eventQueue = eventQueue;
        this.itemManager = itemManager;
        this.imageService = imageService;
        this.policyService = policyService;
    }

    public void processNpcLoot(String loggedInRsn, String npcName, Collection<ItemStack> lootStacks)
    {
        if (!config.enableDropReporting() || isBlank(loggedInRsn)
            || lootStacks == null || lootStacks.isEmpty())
        {
            return;
        }

        String lootSourceName = isBlank(npcName) ? "Unknown NPC" : npcName.trim();
        long minimumDropValueGp = Math.max(0L, policyService.minimumDropValueGp());
        long currentTime = System.currentTimeMillis();
        removeExpiredDedupEntries(currentTime);

        for (ItemStack lootStack : lootStacks)
        {
            if (lootStack == null || lootStack.getQuantity() <= 0 || lootStack.getId() <= 0)
            {
                continue;
            }

            int canonicalItemId = itemManager.canonicalize(lootStack.getId());
            if (canonicalItemId <= 0)
            {
                continue;
            }

            int itemQuantity = lootStack.getQuantity();
            ItemComposition itemComposition = itemManager.getItemComposition(canonicalItemId);
            String itemName = itemComposition == null || isBlank(itemComposition.getName())
                ? "Unknown item"
                : itemComposition.getName().trim();
            int unitPriceGp = Math.max(0, itemManager.getItemPrice(canonicalItemId));
            long totalStackValueGp = (long) unitPriceGp * itemQuantity;

            if (totalStackValueGp < minimumDropValueGp)
            {
                log.debug("Skipping {} x {} from {}: value {} is below threshold {}",
                    itemQuantity, itemName, lootSourceName, totalStackValueGp, minimumDropValueGp);
                continue;
            }

            String dropFingerprint = buildDropFingerprint(
                loggedInRsn, lootSourceName, canonicalItemId, itemQuantity, totalStackValueGp);
            Long previouslyProcessedAt = recentlyProcessedDrops.get(dropFingerprint);
            if (previouslyProcessedAt != null && currentTime - previouslyProcessedAt <= DUPLICATE_WINDOW_MS)
            {
                log.debug("Ignoring duplicate loot callback for itemId={} quantity={} source={}",
                    canonicalItemId, itemQuantity, lootSourceName);
                continue;
            }
            recentlyProcessedDrops.put(dropFingerprint, currentTime);

            Map<String, Object> dropPayload = new LinkedHashMap<>();
            dropPayload.put("itemId", canonicalItemId);
            dropPayload.put("itemName", itemName);
            dropPayload.put("quantity", itemQuantity);
            dropPayload.put("unitPrice", unitPriceGp);
            dropPayload.put("totalValue", totalStackValueGp);
            dropPayload.put("npcName", lootSourceName);

            if (config.attachItemIcons())
            {
                addItemImages(dropPayload, canonicalItemId, itemQuantity);
            }

            Runnable enqueueDrop = () ->
            {
                eventQueue.enqueue(PlankerEvent.builder()
                    .eventType("LOOT_DROP")
                    .rsn(loggedInRsn.trim())
                    .data(dropPayload)
                    .build());
                log.debug("Queued qualifying drop: itemId={} quantity={} totalValue={}",
                    canonicalItemId, itemQuantity, totalStackValueGp);
            };

            boolean includeScreenshot = config.attachScreenshots()
                && config.screenshotDrops()
                && policyService.screenshotsEnabled()
                && totalStackValueGp >= policyService.minimumDropScreenshotValueGp();
            if (includeScreenshot)
            {
                imageService.addScreenshotAsync(dropPayload, enqueueDrop);
            }
            else
            {
                enqueueDrop.run();
            }
        }
    }

    private void addItemImages(Map<String, Object> dropPayload, int itemId, int quantity)
    {
        try
        {
            BufferedImage sourceItemImage = itemManager.getImage(itemId, quantity, false);
            if (sourceItemImage == null)
            {
                return;
            }

            putEncodedImage(dropPayload, "itemIconBase64", sourceItemImage);
            putEncodedImage(dropPayload, "itemLargeBase64", createCenteredCanvas(sourceItemImage, 256, 5));
            putEncodedImage(dropPayload, "itemHeroBase64", createCenteredCanvas(sourceItemImage, 512, 9));
        }
        catch (RuntimeException exception)
        {
            log.debug("Unable to generate item imagery for itemId={}: {}", itemId, exception.getMessage());
            log.trace("Item imagery generation failure", exception);
        }
    }

    private BufferedImage createCenteredCanvas(BufferedImage sourceImage, int canvasSize, int maximumScale)
    {
        BufferedImage centeredImage = new BufferedImage(canvasSize, canvasSize, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = centeredImage.createGraphics();
        try
        {
            graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
                RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_OFF);

            int scaleByWidth = Math.max(1, (canvasSize - 32) / Math.max(1, sourceImage.getWidth()));
            int scaleByHeight = Math.max(1, (canvasSize - 32) / Math.max(1, sourceImage.getHeight()));
            int selectedScale = Math.max(1,
                Math.min(maximumScale, Math.min(scaleByWidth, scaleByHeight)));
            int renderedWidth = sourceImage.getWidth() * selectedScale;
            int renderedHeight = sourceImage.getHeight() * selectedScale;
            int horizontalOffset = (canvasSize - renderedWidth) / 2;
            int verticalOffset = (canvasSize - renderedHeight) / 2;
            graphics.drawImage(sourceImage, horizontalOffset, verticalOffset,
                renderedWidth, renderedHeight, null);
            return centeredImage;
        }
        finally
        {
            graphics.dispose();
        }
    }

    private void putEncodedImage(Map<String, Object> imagePayload, String payloadKey, BufferedImage image)
    {
        try (ByteArrayOutputStream encodedImageBuffer = new ByteArrayOutputStream())
        {
            if (!ImageIO.write(image, "png", encodedImageBuffer))
            {
                return;
            }
            byte[] pngBytes = encodedImageBuffer.toByteArray();
            if (pngBytes.length == 0 || pngBytes.length > MAX_IMAGE_BYTES)
            {
                log.debug("Skipping {} because its PNG size was {} bytes", payloadKey, pngBytes.length);
                return;
            }
            imagePayload.put(payloadKey, Base64.getEncoder().encodeToString(pngBytes));
        }
        catch (IOException exception)
        {
            log.debug("Unable to encode {}: {}", payloadKey, exception.getMessage());
            log.trace("Image encoding failure", exception);
        }
    }

    private String buildDropFingerprint(String loggedInRsn, String npcName, int itemId,
        int quantity, long totalValueGp)
    {
        return loggedInRsn.toLowerCase(Locale.ROOT) + '|'
            + npcName.toLowerCase(Locale.ROOT) + '|'
            + itemId + '|' + quantity + '|' + totalValueGp;
    }

    private void removeExpiredDedupEntries(long currentTime)
    {
        Iterator<Map.Entry<String, Long>> dropIterator = recentlyProcessedDrops.entrySet().iterator();
        while (dropIterator.hasNext())
        {
            Map.Entry<String, Long> recordedDrop = dropIterator.next();
            if (currentTime - recordedDrop.getValue() > DEDUP_ENTRY_MAX_AGE_MS)
            {
                dropIterator.remove();
            }
        }
    }

    private boolean isBlank(String text)
    {
        return text == null || text.trim().isEmpty();
    }
}

package com.planker;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.planker.model.NotificationPolicy;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import lombok.Data;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

@Slf4j
public class NotificationPolicyService
{
    private final PlankerApiClient apiClient;
    private final Gson gson;
    private final Path policyCacheFile;
    private final AtomicBoolean refreshInProgress = new AtomicBoolean();
    private volatile NotificationPolicy activePolicy = new NotificationPolicy();

    @Inject
    public NotificationPolicyService(PlankerApiClient apiClient, Gson gson)
    {
        this.apiClient = apiClient;
        this.gson = gson;
        this.policyCacheFile = RuneLite.RUNELITE_DIR.toPath()
            .resolve("planker")
            .resolve("policy-cache.json");
        loadCachedPolicy();
    }

    public void refresh()
    {
        if (!refreshInProgress.compareAndSet(false, true))
        {
            log.debug("Skipped overlapping PlankRS policy refresh");
            return;
        }

        apiClient.fetchPolicy(new PlankerApiClient.PolicyCallback()
        {
            @Override
            public void onSuccess(NotificationPolicy receivedPolicy)
            {
                refreshInProgress.set(false);
                if (!isValid(receivedPolicy))
                {
                    log.warn("Ignoring incomplete PlankRS notification policy response");
                    return;
                }

                activePolicy = receivedPolicy;
                persistPolicy(receivedPolicy);
                log.info(
                    "Loaded PlankRS policy v{}: drops >= {} gp, screenshots >= {} gp, "
                        + "level schedule every 5 through {}, every level from {}",
                    receivedPolicy.getVersion(),
                    receivedPolicy.getDrops().getMinimumValueGp(),
                    receivedPolicy.getScreenshots().getDropMinimumValueGp(),
                    receivedPolicy.getLevels().getEveryFiveThrough(),
                    receivedPolicy.getLevels().getEveryLevelFrom());
            }

            @Override
            public void onFailure(String failureMessage)
            {
                refreshInProgress.set(false);
                log.warn("Unable to refresh PlankRS notification policy; retaining current policy: {}",
                    failureMessage == null ? "request failed" : failureMessage);
            }
        });
    }

    private void loadCachedPolicy()
    {
        try
        {
            if (!Files.exists(policyCacheFile) || Files.size(policyCacheFile) == 0L)
            {
                return;
            }

            String serializedCache = new String(
                Files.readAllBytes(policyCacheFile), StandardCharsets.UTF_8);
            CachedPolicy cachedPolicy = gson.fromJson(serializedCache, CachedPolicy.class);
            if (cachedPolicy != null && isValid(cachedPolicy.getPolicy()))
            {
                activePolicy = cachedPolicy.getPolicy();
                log.info("Loaded cached PlankRS policy v{} retrieved at {}: drops >= {} gp",
                    activePolicy.getVersion(),
                    cachedPolicy.getRetrievedAt(),
                    activePolicy.getDrops().getMinimumValueGp());
                return;
            }

            log.warn("Cached PlankRS policy is incomplete; removing it");
            deleteInvalidCache();
        }
        catch (IOException | JsonParseException exception)
        {
            log.warn("Unable to load the cached PlankRS policy; using defaults");
            log.debug("Cached policy load failure", exception);
            deleteInvalidCache();
        }
    }

    private void deleteInvalidCache()
    {
        try
        {
            Files.deleteIfExists(policyCacheFile);
        }
        catch (IOException deletionFailure)
        {
            log.warn("Unable to remove the invalid policy cache: {}", deletionFailure.getMessage());
            log.debug("Policy cache deletion failure", deletionFailure);
        }
    }

    private void persistPolicy(NotificationPolicy notificationPolicy)
    {
        try
        {
            Files.createDirectories(policyCacheFile.getParent());
            CachedPolicy cachedPolicy = new CachedPolicy();
            cachedPolicy.setRetrievedAt(Instant.now().toString());
            cachedPolicy.setPolicy(notificationPolicy);

            Path temporaryPolicyFile = policyCacheFile.resolveSibling(
                policyCacheFile.getFileName() + ".tmp");
            Files.write(
                temporaryPolicyFile,
                gson.toJson(cachedPolicy).getBytes(StandardCharsets.UTF_8));
            try
            {
                Files.move(
                    temporaryPolicyFile,
                    policyCacheFile,
                    StandardCopyOption.REPLACE_EXISTING,
                    StandardCopyOption.ATOMIC_MOVE);
            }
            catch (IOException atomicMoveFailure)
            {
                log.debug("Atomic policy-cache replacement unavailable; using standard replacement");
                Files.move(
                    temporaryPolicyFile,
                    policyCacheFile,
                    StandardCopyOption.REPLACE_EXISTING);
            }
        }
        catch (IOException persistenceFailure)
        {
            log.warn("Unable to persist the PlankRS policy cache: {}", persistenceFailure.getMessage());
            log.debug("Policy cache persistence failure", persistenceFailure);
        }
    }

    private boolean isValid(NotificationPolicy notificationPolicy)
    {
        if (notificationPolicy == null
            || notificationPolicy.getDrops() == null
            || notificationPolicy.getLevels() == null
            || notificationPolicy.getScreenshots() == null)
        {
            return false;
        }

        NotificationPolicy.Levels levelPolicy = notificationPolicy.getLevels();
        return levelPolicy.getEveryFiveThrough() >= 0
            && levelPolicy.getEveryLevelFrom() >= 1
            && levelPolicy.getMaximumVirtualLevel() >= levelPolicy.getEveryLevelFrom();
    }

    public long minimumDropValueGp()
    {
        return Math.max(0L, activePolicy.getDrops().getMinimumValueGp());
    }

    public long minimumDropScreenshotValueGp()
    {
        return Math.max(0L, activePolicy.getScreenshots().getDropMinimumValueGp());
    }

    public boolean screenshotsEnabled()
    {
        return activePolicy.getScreenshots().isEnabled();
    }

    public boolean screenshotLevelUps()
    {
        return screenshotsEnabled() && activePolicy.getScreenshots().isLevelUps();
    }

    public boolean screenshotQuests()
    {
        return screenshotsEnabled() && activePolicy.getScreenshots().isQuests();
    }

    public boolean screenshotCollectionLogs()
    {
        return screenshotsEnabled() && activePolicy.getScreenshots().isCollectionLogs();
    }

    public boolean screenshotCombatAchievements()
    {
        return screenshotsEnabled() && activePolicy.getScreenshots().isCombatAchievements();
    }

    public boolean shouldBroadcastLevel(int level)
    {
        NotificationPolicy.Levels levelPolicy = activePolicy.getLevels();
        if (level < 5 || level > levelPolicy.getMaximumVirtualLevel())
        {
            return false;
        }
        if (level <= levelPolicy.getEveryFiveThrough())
        {
            return level % 5 == 0;
        }
        return level >= levelPolicy.getEveryLevelFrom();
    }

    public int policyVersion()
    {
        return Math.max(0, activePolicy.getVersion());
    }

    @Data
    private static class CachedPolicy
    {
        private String retrievedAt;
        private NotificationPolicy policy;
    }
}

package com.planker;

import com.google.gson.Gson;
import com.planker.model.InstallationCheckIn;
import com.planker.model.InstallationCheckInResponse;
import com.planker.model.NotificationPolicy;
import com.planker.model.PlankerEvent;
import java.io.IOException;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
public class PlankerApiClient
{
    private static final MediaType JSON_MEDIA_TYPE = MediaType.get("application/json; charset=utf-8");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final AuthenticatedRequestFactory requestFactory;
    private final ApiResponseInterpreter responseInterpreter;

    @Inject
    public PlankerApiClient(OkHttpClient httpClient, Gson gson, AuthenticatedRequestFactory requestFactory, ApiResponseInterpreter responseInterpreter)
    {
        this.httpClient = httpClient.newBuilder()
            .connectTimeout(10, TimeUnit.SECONDS)
            .readTimeout(15, TimeUnit.SECONDS)
            .writeTimeout(15, TimeUnit.SECONDS)
            .build();
        this.gson = gson;
        this.requestFactory = requestFactory;
        this.responseInterpreter = responseInterpreter;
    }

    public void send(PlankerEvent gameEvent, ResultCallback callback)
    {
        Request eventRequest;
        try
        {
            eventRequest = requestFactory.create("api/v1/events")
                .post(RequestBody.create(JSON_MEDIA_TYPE, gson.toJson(gameEvent)))
                .build();
        }
        catch (IllegalArgumentException configurationError)
        {
            callback.onFailure(new ApiFailure(
                0, configurationError.getMessage(), true, false, 0L));
            return;
        }

        httpClient.newCall(eventRequest).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call requestCall, IOException networkFailure)
            {
                log.debug("Event submission failed for event {}: {}",
                    gameEvent == null ? "unknown" : gameEvent.getEventId(), responseInterpreter.safeMessage(networkFailure));
                log.trace("Event submission failure", networkFailure);
                callback.onFailure(new ApiFailure(
                    0, responseInterpreter.safeMessage(networkFailure), false, true, 0L));
            }

            @Override
            public void onResponse(Call requestCall, Response httpResponse) throws IOException
            {
                try (Response closeableResponse = httpResponse)
                {
                    String responseBody = readResponseBody(closeableResponse);
                    if (!closeableResponse.isSuccessful())
                    {
                        callback.onFailure(responseInterpreter.toFailure(
                            closeableResponse.code(), closeableResponse.header("Retry-After")));
                        return;
                    }
                    callback.onSuccess();
                }
                catch (RuntimeException callbackFailure)
                {
                    log.error("Unexpected event response handling failure: {}", callbackFailure.getMessage());
                    log.debug("Event response handling failure", callbackFailure);
                    callback.onFailure(new ApiFailure(
                        0, "Unexpected response handling failure.", false, true, 0L));
                }
            }
        });
    }

    public void checkIn(InstallationCheckIn checkInPayload, CheckInCallback callback)
    {
        Request checkInRequest;
        try
        {
            checkInRequest = requestFactory.create("api/v1/installations/check-in")
                .post(RequestBody.create(JSON_MEDIA_TYPE, gson.toJson(checkInPayload)))
                .build();
        }
        catch (IllegalArgumentException configurationError)
        {
            callback.onFailure(configurationError.getMessage());
            return;
        }

        httpClient.newCall(checkInRequest).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call requestCall, IOException networkFailure)
            {
                log.debug("Plugin check-in request failed: {}", responseInterpreter.safeMessage(networkFailure));
                log.trace("Plugin check-in failure", networkFailure);
                callback.onFailure(responseInterpreter.friendlyConnectionError(0, responseInterpreter.safeMessage(networkFailure)));
            }

            @Override
            public void onResponse(Call requestCall, Response httpResponse) throws IOException
            {
                try (Response closeableResponse = httpResponse)
                {
                    String responseBody = readResponseBody(closeableResponse);
                    if (!closeableResponse.isSuccessful())
                    {
                        callback.onFailure(responseInterpreter.friendlyConnectionError(closeableResponse.code(), responseBody));
                        return;
                    }

                    try
                    {
                        InstallationCheckInResponse checkInResponse =
                            gson.fromJson(responseBody, InstallationCheckInResponse.class);
                        if (checkInResponse == null)
                        {
                            throw new IllegalStateException("Check-in response was empty");
                        }
                        callback.onSuccess(checkInResponse);
                    }
                    catch (RuntimeException invalidPayload)
                    {
                        log.warn("Plugin check-in returned an invalid response payload");
                        log.debug("Invalid check-in response payload", invalidPayload);
                        callback.onFailure("The server returned an invalid connection response.");
                    }
                }
            }
        });
    }

    public void fetchPolicy(PolicyCallback callback)
    {
        Request policyRequest;
        try
        {
            policyRequest = requestFactory.create("api/v1/policy").get().build();
        }
        catch (IllegalArgumentException configurationError)
        {
            callback.onFailure(configurationError.getMessage());
            return;
        }

        httpClient.newCall(policyRequest).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call requestCall, IOException networkFailure)
            {
                log.debug("Policy request failed: {}", responseInterpreter.safeMessage(networkFailure));
                log.trace("Policy request failure", networkFailure);
                callback.onFailure(responseInterpreter.safeMessage(networkFailure));
            }

            @Override
            public void onResponse(Call requestCall, Response httpResponse) throws IOException
            {
                try (Response closeableResponse = httpResponse)
                {
                    String responseBody = readResponseBody(closeableResponse);
                    if (!closeableResponse.isSuccessful())
                    {
                        callback.onFailure("HTTP " + closeableResponse.code());
                        return;
                    }

                    try
                    {
                        NotificationPolicy notificationPolicy =
                            gson.fromJson(responseBody, NotificationPolicy.class);
                        if (notificationPolicy == null)
                        {
                            throw new IllegalStateException("Policy response was empty");
                        }
                        callback.onSuccess(notificationPolicy);
                    }
                    catch (RuntimeException invalidPayload)
                    {
                        log.warn("Policy endpoint returned an invalid response payload");
                        log.debug("Invalid policy response payload", invalidPayload);
                        callback.onFailure("The server returned an invalid policy response.");
                    }
                }
            }
        });
    }

    private String readResponseBody(Response httpResponse) throws IOException
    {
        if (httpResponse.body() == null)
        {
            return "";
        }

        return httpResponse.body().string();
    }

    public interface ResultCallback
    {
        void onSuccess();
        void onFailure(ApiFailure apiFailure);
    }

    @Value
    public static class ApiFailure
    {
        int statusCode;
        String message;
        boolean authenticationFailure;
        boolean temporaryFailure;
        long retryAfterMillis;

        public boolean isPermanentFailure()
        {
            return !authenticationFailure && !temporaryFailure;
        }
    }

    public interface CheckInCallback
    {
        void onSuccess(InstallationCheckInResponse checkInResponse);
        void onFailure(String failureMessage);
    }

    public interface PolicyCallback
    {
        void onSuccess(NotificationPolicy notificationPolicy);
        void onFailure(String failureMessage);
    }
}

