import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
    name = "PlankRS Clan",
    description = "Reports opted-in events for the logged-in account to the PlankRS clan Discord",
    tags = {"clan", "discord", "drops", "quests", "achievements", "chat"}
)
public class PlankerPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private PlankerConfig config;
    @Inject private ConfigManager configManager;
    @Inject private EventQueue eventQueue;
    @Inject private ScheduledExecutorService executor;
    @Inject private LootEventService lootEventService;
    @Inject private PlayerEventService playerEventService;
    @Inject private ClanChatRelayService clanChatRelayService;
    @Inject private NotificationPolicyService notificationPolicyService;
    @Inject private PluginConnectionService pluginConnectionService;
    @Inject private PrivacyConfirmationService privacyConfirmationService;

    private final List<ScheduledFuture<?>> scheduledTasks = new ArrayList<>();

    @Provides
    PlankerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(PlankerConfig.class);
    }

    @Override
    protected void startUp()
    {
        log.info("PlankRS Clan started");
        scheduledTasks.add(executor.scheduleWithFixedDelay(eventQueue::retryPending, 5, 5, TimeUnit.SECONDS));
        scheduledTasks.add(executor.scheduleWithFixedDelay(
            () -> pluginConnectionService.checkIn(resolveRsn(), false),
            5,
            5,
            TimeUnit.MINUTES
        ));
        scheduledTasks.add(executor.scheduleWithFixedDelay(
            notificationPolicyService::refresh,
            15,
            15,
            TimeUnit.MINUTES
        ));
    }

    @Override
    protected void shutDown()
    {
        for (ScheduledFuture<?> scheduledTask : scheduledTasks)
        {
            scheduledTask.cancel(false);
        }
        scheduledTasks.clear();
        log.info("PlankRS Clan stopped with {} queued event(s)", eventQueue.size());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            eventQueue.retryPending();
            playerEventService.resetForLogin();
            pluginConnectionService.checkIn(resolveRsn(), false);
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"planker".equals(event.getGroup()))
        {
            return;
        }

        if ("testConnection".equals(event.getKey()) && config.testConnection())
        {
            pluginConnectionService.testConnection(resolveRsn());
            configManager.setConfiguration("planker", "testConnection", false);
            return;
        }

        if ("enableClanChatRelay".equals(event.getKey()) && config.enableClanChatRelay())
        {
            if (privacyConfirmationService.consumeConfirmedClanChatChange())
            {
                return;
            }

            privacyConfirmationService.requestClanChatConfirmation();
            return;
        }

        if ("attachScreenshots".equals(event.getKey()) && config.attachScreenshots())
        {
            if (privacyConfirmationService.consumeConfirmedScreenshotChange())
            {
                return;
            }

            privacyConfirmationService.requestScreenshotConfirmation();
            return;
        }

        if ("apiUrl".equals(event.getKey()) || "apiKey".equals(event.getKey()))
        {
            eventQueue.resumeAfterConfigurationChange();
            pluginConnectionService.checkIn(resolveRsn(), false);
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        playerEventService.onStatChanged(resolveRsn(), event);
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        String loggedInRsn = resolveRsn();
        playerEventService.onChatMessage(loggedInRsn, event);
        clanChatRelayService.onChatMessage(loggedInRsn, event);
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        String loggedInRsn = resolveRsn();
        if (loggedInRsn == null)
        {
            return;
        }

        String npcName = event.getNpc() == null ? null : event.getNpc().getName();
        lootEventService.processNpcLoot(loggedInRsn, npcName, event.getItems());
    }

    @Subscribe
    public void onServerNpcLoot(ServerNpcLoot event)
    {
        String loggedInRsn = resolveRsn();
        if (loggedInRsn == null)
        {
            return;
        }

        String npcName = event.getComposition() == null ? null : event.getComposition().getName();
        lootEventService.processNpcLoot(loggedInRsn, npcName, event.getItems());
    }

    private String resolveRsn()
    {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
        {
            return null;
        }

        return client.getLocalPlayer().getName();
    }
}

package com.planker;

import com.planker.model.PlankerEvent;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.StatChanged;
import net.runelite.client.util.Text;

@Slf4j
public class PlayerEventService
{
    private static final long LOGIN_LEVEL_SUPPRESSION_MS = 10_000L;
    private static final long CHAT_DEDUP_RETENTION_MS = 10_000L;
    private static final long CHAT_DUPLICATE_WINDOW_MS = 3_000L;
    private static final Pattern COLLECTION_LOG_PATTERN = Pattern.compile(
        "(?i)new item added to your collection log:?\\s*(.+)");
    private static final Pattern QUEST_COMPLETION_PATTERN = Pattern.compile(
        "(?i)(?:congratulations[,]*)?\\s*you(?:'ve| have) completed (?:the quest[: ]+)?(.+?)[.!]?$|quest completed[: ]+(.+)");
    private static final Pattern COMBAT_ACHIEVEMENT_PATTERN = Pattern.compile(
        "(?i)(?:combat (?:task|achievement) completed)[: ]+(.+)");
    private static final Pattern COMBAT_TIER_SUFFIX_PATTERN = Pattern.compile(
        "^(.*?)(?:\\s*\\((Easy|Medium|Hard|Elite|Master|Grandmaster)\\))?$",
        Pattern.CASE_INSENSITIVE);

    private final Client client;
    private final PlankerConfig config;
    private final EventQueue eventQueue;
    private final EventImageService imageService;
    private final NotificationPolicyService policyService;
    private final Map<Skill, Integer> lastKnownXpBySkill = new EnumMap<>(Skill.class);
    private final Map<String, Long> recentSystemMessages = new LinkedHashMap<>();
    private long suppressLevelEventsUntil;

    @Inject
    public PlayerEventService(Client client, PlankerConfig config, EventQueue eventQueue,
        EventImageService imageService, NotificationPolicyService policyService)
    {
        this.client = client;
        this.config = config;
        this.eventQueue = eventQueue;
        this.imageService = imageService;
        this.policyService = policyService;
    }

    public void resetForLogin()
    {
        lastKnownXpBySkill.clear();
        recentSystemMessages.clear();
        suppressLevelEventsUntil = System.currentTimeMillis() + LOGIN_LEVEL_SUPPRESSION_MS;
    }

    public void onStatChanged(String loggedInRsn, StatChanged statChangedEvent)
    {
        if (!config.enableLevelReporting() || isBlank(loggedInRsn) || statChangedEvent == null)
        {
            return;
        }

        Skill changedSkill = statChangedEvent.getSkill();
        if (changedSkill == null || changedSkill == Skill.OVERALL)
        {
            return;
        }

        int currentXp = Math.max(0, statChangedEvent.getXp());
        Integer previousXp = lastKnownXpBySkill.put(changedSkill, currentXp);
        if (System.currentTimeMillis() < suppressLevelEventsUntil || previousXp == null || currentXp <= previousXp)
        {
            return;
        }

        int previousLevel = net.runelite.api.Experience.getLevelForXp(previousXp);
        int currentLevel = net.runelite.api.Experience.getLevelForXp(currentXp);
        if (currentLevel <= previousLevel || !policyService.shouldBroadcastLevel(currentLevel))
        {
            return;
        }

        Map<String, Object> levelPayload = new LinkedHashMap<>();
        levelPayload.put("skill", formatSkillName(changedSkill));
        levelPayload.put("level", currentLevel);
        imageService.addSkillBadge(levelPayload, changedSkill, currentLevel);
        enqueueWithOptionalScreenshot(
            loggedInRsn,
            "LEVEL_UP",
            levelPayload,
            config.attachScreenshots()
                && config.screenshotLevelUps()
                && policyService.screenshotLevelUps());
    }

    public void onChatMessage(String loggedInRsn, ChatMessage chatMessageEvent)
    {
        if (isBlank(loggedInRsn) || chatMessageEvent == null
            || chatMessageEvent.getType() != ChatMessageType.GAMEMESSAGE
            || chatMessageEvent.getMessage() == null)
        {
            return;
        }

        String systemMessage = Text.removeTags(chatMessageEvent.getMessage()).trim();
        if (systemMessage.isEmpty() || isDuplicateSystemMessage(systemMessage))
        {
            return;
        }

        Matcher collectionLogMatcher = COLLECTION_LOG_PATTERN.matcher(systemMessage);
        if (config.enableCollectionLogReporting() && collectionLogMatcher.find())
        {
            String unlockedItemName = collectionLogMatcher.group(1).trim();
            if (!unlockedItemName.isEmpty())
            {
                Map<String, Object> collectionLogPayload = new LinkedHashMap<>();
                collectionLogPayload.put("itemName", unlockedItemName);
                imageService.addBadge(collectionLogPayload, "LOG", "Collection Log");
                enqueueWithOptionalScreenshot(
                    loggedInRsn,
                    "COLLECTION_LOG",
                    collectionLogPayload,
                    config.attachScreenshots()
                        && config.screenshotCollectionLogs()
                        && policyService.screenshotCollectionLogs());
            }
            return;
        }

        Matcher questMatcher = QUEST_COMPLETION_PATTERN.matcher(systemMessage);
        if (config.enableQuestReporting() && questMatcher.find())
        {
            String completedQuestName = questMatcher.group(1) != null
                ? questMatcher.group(1).trim()
                : questMatcher.group(2) == null ? "" : questMatcher.group(2).trim();
            if (!completedQuestName.isEmpty())
            {
                Map<String, Object> questPayload = new LinkedHashMap<>();
                questPayload.put("questName", completedQuestName);
                imageService.addBadge(questPayload, "QUEST", "Completed");
                enqueueWithOptionalScreenshot(
                    loggedInRsn,
                    "QUEST_COMPLETED",
                    questPayload,
                    config.attachScreenshots()
                        && config.screenshotQuests()
                        && policyService.screenshotQuests());
            }
            return;
        }

        Matcher combatAchievementMatcher = COMBAT_ACHIEVEMENT_PATTERN.matcher(systemMessage);
        if (config.enableCombatAchievementReporting() && combatAchievementMatcher.find())
        {
            String rawAchievementName = combatAchievementMatcher.group(1).trim();
            Matcher tierMatcher = COMBAT_TIER_SUFFIX_PATTERN.matcher(rawAchievementName);
            if (!tierMatcher.matches())
            {
                return;
            }

            String achievementName = tierMatcher.group(1).trim();
            String achievementTier = tierMatcher.group(2);
            if (achievementName.isEmpty())
            {
                return;
            }

            Map<String, Object> combatAchievementPayload = new LinkedHashMap<>();
            combatAchievementPayload.put("achievementName", achievementName);
            if (achievementTier != null)
            {
                combatAchievementPayload.put("tier", achievementTier);
            }
            imageService.addBadge(
                combatAchievementPayload,
                "CA",
                achievementTier == null ? "Combat Task" : achievementTier);
            enqueueWithOptionalScreenshot(
                loggedInRsn,
                "COMBAT_ACHIEVEMENT",
                combatAchievementPayload,
                config.attachScreenshots()
                    && config.screenshotCombatAchievements()
                    && policyService.screenshotCombatAchievements());
        }
    }

    private void enqueueWithOptionalScreenshot(String loggedInRsn, String eventType,
        Map<String, Object> eventPayload, boolean includeScreenshot)
    {
        Runnable enqueueEvent = () -> enqueuePlayerEvent(loggedInRsn, eventType, eventPayload);
        if (includeScreenshot)
        {
            imageService.addScreenshotAsync(eventPayload, enqueueEvent);
        }
        else
        {
            enqueueEvent.run();
        }
    }

    private void enqueuePlayerEvent(String loggedInRsn, String eventType, Map<String, Object> eventPayload)
    {
        eventQueue.enqueue(PlankerEvent.builder()
            .eventType(eventType)
            .rsn(loggedInRsn)
            .data(eventPayload)
            .build());
        log.debug("Queued player event type={}", eventType);
    }

    private boolean isDuplicateSystemMessage(String systemMessage)
    {
        long currentTime = System.currentTimeMillis();
        recentSystemMessages.entrySet().removeIf(
            recordedMessage -> currentTime - recordedMessage.getValue() > CHAT_DEDUP_RETENTION_MS);
        String normalizedMessage = systemMessage.toLowerCase(Locale.ROOT);
        Long previouslySeenAt = recentSystemMessages.put(normalizedMessage, currentTime);
        return previouslySeenAt != null && currentTime - previouslySeenAt < CHAT_DUPLICATE_WINDOW_MS;
    }

    private String formatSkillName(Skill skill)
    {
        String normalizedSkillName = skill.name().toLowerCase(Locale.ROOT).replace('_', ' ');
        return Character.toUpperCase(normalizedSkillName.charAt(0)) + normalizedSkillName.substring(1);
    }

    private boolean isBlank(String text)
    {
        return text == null || text.trim().isEmpty();
    }
}

package com.planker;

import com.planker.model.InstallationCheckIn;
import com.planker.model.InstallationCheckInResponse;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;

@Slf4j
public class PluginConnectionService
{
    private final PlankerApiClient apiClient;
    private final EventQueue eventQueue;
    private final NotificationPolicyService policyService;
    private final Notifier notifier;
    private final Client client;
    private final ClientThread clientThread;
    private final AtomicBoolean checkInInProgress = new AtomicBoolean();
    private volatile String lastConnectionError;
    private volatile boolean updateNoticeShown;
    private volatile boolean requiredUpdateNoticeShown;

    @Inject
    public PluginConnectionService(
        PlankerApiClient apiClient,
        EventQueue eventQueue,
        NotificationPolicyService policyService,
        Notifier notifier,
        Client client,
        ClientThread clientThread)
    {
        this.apiClient = apiClient;
        this.eventQueue = eventQueue;
        this.policyService = policyService;
        this.notifier = notifier;
        this.client = client;
        this.clientThread = clientThread;
    }

    public void testConnection(String loggedInRsn)
    {
        showStatusMessage("Testing PlankRS connection...");
        checkIn(loggedInRsn, true);
    }

    public void showStatusMessage(String message)
    {
        if (message == null || message.trim().isEmpty())
        {
            return;
        }

        String statusMessage = message.trim();
        clientThread.invokeLater(() -> client.addChatMessage(
            ChatMessageType.CONSOLE,
            "PlankRS",
            statusMessage,
            null
        ));
    }

    public void checkIn(String loggedInRsn, boolean notifyUser)
    {
        if (loggedInRsn == null || loggedInRsn.trim().isEmpty())
        {
            handleConnectionFailure(
                "Log in to RuneScape before testing the PlankRS connection.", notifyUser);
            return;
        }

        if (!checkInInProgress.compareAndSet(false, true))
        {
            log.debug("Skipped overlapping PlankRS check-in");
            return;
        }

        InstallationCheckIn checkInPayload = InstallationCheckIn.builder()
            .pluginVersion(PluginVersion.VERSION)
            .policyVersion(policyService.policyVersion())
            .queuedEventCount(eventQueue.size())
            .rsn(loggedInRsn.trim())
            .lastError(lastConnectionError)
            .build();

        apiClient.checkIn(checkInPayload, new PlankerApiClient.CheckInCallback()
        {
            @Override
            public void onSuccess(InstallationCheckInResponse checkInResponse)
            {
                checkInInProgress.set(false);
                lastConnectionError = null;

                if (checkInResponse.isUpdateRequired())
                {
                    eventQueue.pauseForRequiredUpdate();
                    String requiredUpdateMessage = "PlankRS plugin " + PluginVersion.VERSION
                        + " is no longer supported. Update to "
                        + safeVersion(checkInResponse.getLatestPluginVersion()) + ".";
                    lastConnectionError = requiredUpdateMessage;
                    log.warn(requiredUpdateMessage);
                    if (!requiredUpdateNoticeShown)
                    {
                        notifier.notify(requiredUpdateMessage);
                        requiredUpdateNoticeShown = true;
                    }
                    if (notifyUser)
                    {
                        showStatusMessage(requiredUpdateMessage);
                    }
                    return;
                }

                requiredUpdateNoticeShown = false;
                eventQueue.resumeAfterConfigurationChange();
                policyService.refresh();
                log.info("Connected to PlankRS using plugin version {} and policy version {}",
                    PluginVersion.VERSION, checkInResponse.getPolicyVersion());

                if (checkInResponse.isUpdateAvailable() && !updateNoticeShown)
                {
                    notifier.notify("A newer PlankRS plugin is available: "
                        + safeVersion(checkInResponse.getLatestPluginVersion())
                        + " (current " + PluginVersion.VERSION + ").");
                    updateNoticeShown = true;
                    if (notifyUser)
                    {
                        showStatusMessage("Connected to PlankRS. A plugin update is available.");
                    }
                }
                else if (!checkInResponse.isUpdateAvailable())
                {
                    updateNoticeShown = false;
                    if (notifyUser)
                    {
                        notifier.notify("PlankRS connected successfully.");
                        showStatusMessage("Connected to PlankRS.");
                    }
                }
                else if (notifyUser)
                {
                    notifier.notify("PlankRS connected successfully; an update is available.");
                    showStatusMessage("Connected to PlankRS. A plugin update is available.");
                }
            }

            @Override
            public void onFailure(String failureMessage)
            {
                checkInInProgress.set(false);
                handleConnectionFailure(failureMessage, notifyUser);
            }
        });
    }

    private void handleConnectionFailure(String failureMessage, boolean notifyUser)
    {
        String safeFailureMessage = failureMessage == null || failureMessage.trim().isEmpty()
            ? "Connection check failed."
            : failureMessage.trim();
        lastConnectionError = safeFailureMessage;
        log.warn("PlankRS connection check failed: {}", safeFailureMessage);
        if (notifyUser)
        {
            notifier.notify("PlankRS connection failed: " + safeFailureMessage);
            showStatusMessage("Connection failed: " + safeFailureMessage);
        }
    }

    private String safeVersion(String version)
    {
        return version == null || version.trim().isEmpty() ? "the latest version" : version.trim();
    }
}

package com.planker;

